import 'dart:ffi' hide Size;
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:glow/glow.dart';

typedef _AllocN = Pointer<Uint16> Function(Uint32, IntPtr);
typedef _AllocD = Pointer<Uint16> Function(int, int);
typedef _FreeN = IntPtr Function(Pointer<Uint16>);
typedef _FreeD = int Function(Pointer<Uint16>);
typedef _HandleN = IntPtr Function(Pointer<Uint16>);
typedef _HandleD = int Function(Pointer<Uint16>);
typedef _NameN = Uint32 Function(IntPtr, Pointer<Uint16>, Uint32);
typedef _NameD = int Function(int, Pointer<Uint16>, int);

// Full path of a loaded module, via kernel32 only (no extra packages).
String? loadedPath(String module) {
  final k32 = DynamicLibrary.open('kernel32.dll');
  final alloc = k32.lookupFunction<_AllocN, _AllocD>('LocalAlloc');
  final free = k32.lookupFunction<_FreeN, _FreeD>('LocalFree');
  final handle = k32.lookupFunction<_HandleN, _HandleD>('GetModuleHandleW');
  final name = k32.lookupFunction<_NameN, _NameD>('GetModuleFileNameW');
  final wide = alloc(0x40, (module.length + 1) * 2);
  final buf = alloc(0x40, 2048);
  try {
    for (var i = 0; i < module.length; i++) {
      wide[i] = module.codeUnitAt(i);
    }
    final h = handle(wide);
    if (h == 0) return null;
    final n = name(h, buf, 1024);
    return n == 0 ? null : String.fromCharCodes(buf.asTypedList(n));
  } finally {
    free(wide);
    free(buf);
  }
}

String norm(String p) => File(p).absolute.path.replaceAll('/', r'\').toLowerCase();

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  final controller = OpenGLController();
  controller.initializeGL();
  if (controller.openglFFI.rendererStatus()) {
    throw StateError('renderer unexpectedly active before surface creation');
  }
  if (controller.openglFFI.addIntUniform('payload', 1) ||
      controller.openglFFI.setIntUniform('payload', 2) ||
      controller.openglFFI.removeUniform('payload')) {
    throw StateError('uniform operations succeeded without renderer');
  }
  final expected = Platform.environment['GLOW_PAYLOAD_LIBRARY']!;
  final loaded = loadedPath('flutter_opengl_rust.dll');
  if (loaded == null || norm(loaded) != norm(expected)) {
    throw StateError('unexpected native library: $loaded');
  }
  final size = controller.openglFFI.getTextureSize();
  if (size != const Size(-1, -1)) {
    throw StateError('unexpected initial texture size: $size');
  }
  print('Glow native FFI loaded; inactive renderer and uninitialized texture sentinel queried');
  exit(0);
}

